namespace g2d {

// ---------------------------------------------------------------------------------------------
// §3 formats
// ---------------------------------------------------------------------------------------------

unsigned fmt_bits(uint8_t fmt) {
  const unsigned cls = fmt & 0xF, order = (fmt >> 4) & 3, x = (fmt >> 6) & 1;
  if (fmt & 0x80) {                               // extended codes (v1.6b)
    if (cls <= kX5658) return (order <= 1 && !x) ? 24 : 0;          // 24-bit sources, orders 0 / 1
    // YUV (§3.7): YUY2 / AYUY2 16 bit per pixel, the planar classes 8 (the Y plane); valid codes only
    if (cls == kXYuy2) return order == 0 ? 16 : 0;
    if (cls == kXNv) return (order <= 2 && (!x || order == 0)) ? 8 : 0;
    if (cls == kXYv) return (order <= 2 && !x) ? 8 : 0;
    return 0;
  }
  switch (cls) {
    case kP32: return 32;                         // every order, with or without X
    case kP16: return (order <= 1 && !x) ? 16 : 0;  // RGB565, BGR565
    case kP4444: case kP5551: return x ? 0 : 16;  // four orders
    case kP2222: return x ? 0 : 8;
    default: break;
  }
  if (order != 0 || x) return 0;  // single-order classes
  switch (cls) {
    case kA8: case kL8: case kI8: return 8;
    case kA8L8: return 16;                        // v1.6, source only
    case kA4: case kL4: case kI4: return 4;
    case kA2: case kI2: return 2;
    case kA1: case kI1: return 1;
    default: return 0;
  }
}

const uint8_t kBayer[4][4] = {{0, 8, 2, 10}, {12, 4, 14, 6}, {3, 11, 1, 9}, {15, 7, 13, 5}};

namespace {

// Byte positions (0 = lowest address) of A, R, G, B for each 32-bit channel order (§3.2).
struct Order32 {
  int a, r, g, b;
};
constexpr Order32 kOrder32[4] = {
    {3, 0, 1, 2},  // RGBA: R,G,B,A
    {3, 2, 1, 0},  // BGRA: B,G,R,A
    {0, 1, 2, 3},  // ARGB: A,R,G,B
    {0, 3, 2, 1},  // ABGR: A,B,G,R
};

inline uint8_t byte_of(uint32_t raw, int i) { return uint8_t(raw >> (8 * i)); }

// §3.3 bit replication of an n-bit channel (n = 1..8).
inline uint8_t expand_n(uint32_t c, unsigned n) {
  uint32_t v = 0;
  for (int sh = 8 - int(n); sh > -int(n); sh -= int(n)) v |= sh >= 0 ? c << sh : c >> -sh;
  return uint8_t(v);
}
// §3.4 rounding to n < 8 bits.
inline uint32_t compress_n(uint32_t c, unsigned n) { return (c * ((1u << n) - 1u) + 127u) / 255u; }

// Packed 16/8-bit classes with four orders (§3.2): bit positions of A, R, G, B and the widths.
struct Layout {
  unsigned pa, pr, pg, pb, wa, wc;
};
Layout packed_layout(unsigned cls, unsigned order) {
  static const char kSeq[4][5] = {"RGBA", "BGRA", "ARGB", "ABGR"};  // from bit 0
  Layout l{};
  l.wc = cls == kP5551 ? 5 : (cls == kP4444 ? 4 : 2);
  l.wa = cls == kP5551 ? 1 : l.wc;
  unsigned pos = 0;
  for (int i = 0; i < 4; ++i) {
    switch (kSeq[order][i]) {
      case 'A': l.pa = pos; pos += l.wa; break;
      case 'R': l.pr = pos; pos += l.wc; break;
      case 'G': l.pg = pos; pos += l.wc; break;
      default:  l.pb = pos; pos += l.wc; break;
    }
  }
  return l;
}

inline uint32_t field(uint32_t raw, unsigned pos, unsigned w) { return (raw >> pos) & ((1u << w) - 1u); }

// d < 0: plain §3.4 rounding; otherwise the §3.6 dither with Bayer value d on R, G, B.
uint32_t compress_impl(uint8_t fmt, Argb c, int d) {
  const unsigned cls = fmt & 0xF, order = (fmt >> 4) & 3;
  const bool x_alpha = (fmt >> 6) & 1;
  auto col = [&](uint32_t v, unsigned n) { return d < 0 ? compress_n(v, n) : dither_channel(v, n, unsigned(d)); };
  switch (cls) {
    case kA8:
      return c.a;
    case kL8:
      return (77u * c.r + 150u * c.g + 29u * c.b + 128u) >> 8;
    case kP16: {
      uint32_t r = col(c.r, 5), g = col(c.g, 6), b = col(c.b, 5);
      return order == 0 ? (r | (g << 5) | (b << 11)) : (b | (g << 5) | (r << 11));
    }
    case kP4444: case kP5551: case kP2222: {
      const Layout l = packed_layout(cls, order);
      return (compress_n(c.a, l.wa) << l.pa) | (col(c.r, l.wc) << l.pr) | (col(c.g, l.wc) << l.pg) |
             (col(c.b, l.wc) << l.pb);
    }
    default: {
      const Order32& o = kOrder32[order];
      uint32_t a = x_alpha ? 0xFFu : c.a;
      return (a << (8 * o.a)) | (uint32_t(c.r) << (8 * o.r)) | (uint32_t(c.g) << (8 * o.g)) |
             (uint32_t(c.b) << (8 * o.b));
    }
  }
}

}  // namespace

namespace {
const uint8_t kGammaLin[256] = G2D_GAMMA_LIN_INIT;
const uint8_t kGammaSrgb[256] = G2D_GAMMA_SRGB_INIT;
}  // namespace

uint8_t gamma_lin(uint8_t c) { return kGammaLin[c]; }
uint8_t gamma_srgb(uint8_t c) { return kGammaSrgb[c]; }

Argb color_apply(Argb c, const ColorUnit& cu) {
  if (cu.gamma == 1) c = Argb{c.a, kGammaLin[c.r], kGammaLin[c.g], kGammaLin[c.b]};
  else if (cu.gamma == 2) c = Argb{c.a, kGammaSrgb[c.r], kGammaSrgb[c.g], kGammaSrgb[c.b]};
  if (!cu.en) return c;
  const int v[4] = {c.a, c.r, c.g, c.b};
  uint8_t o[4];
  for (int i = 0; i < 4; ++i) {
    int64_t s = cu.b[i] + 128;
    for (int j = 0; j < 4; ++j) s += int64_t(cu.m[i][j]) * v[j];
    const int64_t q = s >> 8;   // arithmetic: floor
    o[i] = uint8_t(q < 0 ? 0 : q > 255 ? 255 : q);
  }
  return Argb{o[0], o[1], o[2], o[3]};
}

Argb yuv_expand(uint32_t ayuv, bool bt709) {
  // §3.7: round(1024 k) of the BT.601 / BT.709 limited-range matrix
  static const int K[2][5] = {{1192, 1634, 401, 832, 2066}, {1192, 1836, 218, 546, 2163}};
  const int* k = K[bt709 ? 1 : 0];
  const int y = int((ayuv >> 16) & 0xFF) - 16, u = int((ayuv >> 8) & 0xFF) - 128, v = int(ayuv & 0xFF) - 128;
  auto c = [](int t) { return sat8((t + 512) >> 10); };   // arithmetic shift (floor), then clamp
  return Argb{uint8_t(ayuv >> 24), c(k[0] * y + k[1] * v), c(k[0] * y - k[2] * u - k[3] * v), c(k[0] * y + k[4] * u)};
}

Argb expand(uint8_t fmt, uint32_t raw, const uint32_t* clut) {
  const unsigned cls = fmt & 0xF, order = (fmt >> 4) & 3;
  const bool x_alpha = (fmt >> 6) & 1;
  if (fmt_yuv(fmt)) return yuv_expand(raw, false);   // the assembled {A, Y, U, V} texel, BT.601 (§3.7)
  if (fmt & 0x80) {                               // §3.3 24-bit (v1.6b); order 0 = R in the low field
    if (cls == kX888) {
      const uint8_t lo = uint8_t(raw), mid = uint8_t(raw >> 8), hi = uint8_t(raw >> 16);
      return order == 0 ? Argb{255, lo, mid, hi} : Argb{255, hi, mid, lo};
    }
    const uint32_t c565 = cls == kX8565 ? (raw >> 8) & 0xFFFF : raw & 0xFFFF;
    const uint8_t a = uint8_t(cls == kX8565 ? raw : raw >> 16);
    const uint8_t lo = expand_n(c565 & 0x1F, 5), mid = expand_n((c565 >> 5) & 0x3F, 6),
                  hi = expand_n((c565 >> 11) & 0x1F, 5);
    return order == 0 ? Argb{a, lo, mid, hi} : Argb{a, hi, mid, lo};
  }
  switch (cls) {
    case kA8: return Argb{uint8_t(raw), 255, 255, 255};
    case kA4: return Argb{expand_n(raw & 0xF, 4), 255, 255, 255};
    case kA2: return Argb{expand_n(raw & 0x3, 2), 255, 255, 255};
    case kA1: return Argb{expand_n(raw & 0x1, 1), 255, 255, 255};
    case kL8: {
      const uint8_t l = uint8_t(raw);
      return Argb{255, l, l, l};
    }
    case kL4: {
      const uint8_t l = expand_n(raw & 0xF, 4);
      return Argb{255, l, l, l};
    }
    case kI8: case kI4: case kI2: case kI1:
      return unpack(clut[raw & 0xFF]);
    case kA8L8: {                                 // v1.6: A bits 7:0, L bits 15:8
      const uint8_t l = uint8_t(raw >> 8);
      return Argb{uint8_t(raw), l, l, l};
    }
    case kP16: {
      const uint8_t lo = expand_n(raw & 0x1F, 5), mid = expand_n((raw >> 5) & 0x3F, 6),
                    hi = expand_n((raw >> 11) & 0x1F, 5);
      return order == 0 ? Argb{255, lo, mid, hi} : Argb{255, hi, mid, lo};
    }
    case kP4444: case kP5551: case kP2222: {
      const Layout l = packed_layout(cls, order);
      return Argb{expand_n(field(raw, l.pa, l.wa), l.wa), expand_n(field(raw, l.pr, l.wc), l.wc),
                  expand_n(field(raw, l.pg, l.wc), l.wc), expand_n(field(raw, l.pb, l.wc), l.wc)};
    }
    default: {
      const Order32& o = kOrder32[order];
      return Argb{x_alpha ? uint8_t(255) : byte_of(raw, o.a), byte_of(raw, o.r), byte_of(raw, o.g),
                  byte_of(raw, o.b)};
    }
  }
}

uint32_t compress(uint8_t fmt, Argb c) { return compress_impl(fmt, c, -1); }

uint32_t compress_dither(uint8_t fmt, Argb c, int x, int y) { return compress_impl(fmt, c, kBayer[y & 3][x & 3]); }

// ---------------------------------------------------------------------------------------------
// §5 paint and blend
// ---------------------------------------------------------------------------------------------

Argb color_key(Argb c, const ColorKey keys[4]) {
  for (int k = 0; k < 4; ++k) {
    const ColorKey& key = keys[k];
    if (key.en && key.lr <= c.r && c.r <= key.hr && key.lg <= c.g && c.g <= key.hg && key.lb <= c.b &&
        c.b <= key.hb) {
      c.a = key.alpha;
      return c;
    }
  }
  return c;
}

Argb premultiply(Argb c) { return Argb{c.a, mul8(c.r, c.a), mul8(c.g, c.a), mul8(c.b, c.a)}; }

Argb apply_global_alpha(Argb c, unsigned mode, uint8_t value) {
  if (mode == 1) c.a = value;
  else if (mode == 2) c.a = mul8(c.a, value);
  return c;
}

Argb multiply_color(Argb s, Argb p) {
  return Argb{mul8(s.a, p.a), mul8(s.r, p.r), mul8(s.g, p.g), mul8(s.b, p.b)};
}

bool blend_reads_dst(unsigned mode) { return mode != 0; }

namespace {

// Saturating two-operand steps, evaluated left to right (§5.6).
inline uint8_t add(int a, int b) { return sat8(a + b); }
inline uint8_t sub(int a, int b) { return sat8(a - b); }
inline uint8_t inv(uint8_t x) { return uint8_t(255 - x); }

// One channel of SRC_OVER / DST_OVER; used for colour (c) and alpha (sa/da are the alphas).
inline uint8_t src_over(uint8_t s, uint8_t d, uint8_t sa) { return add(s, mul8(d, inv(sa))); }
inline uint8_t dst_over(uint8_t s, uint8_t d, uint8_t da) { return add(mul8(s, inv(da)), d); }

uint8_t blend_ch(unsigned mode, uint8_t s, uint8_t d, uint8_t sa, uint8_t da) {
  switch (mode) {
    case 0: return s;                                                      // NONE
    case 1: return src_over(s, d, sa);                                     // SRC_OVER
    case 2: return dst_over(s, d, da);                                     // DST_OVER
    case 3: return mul8(s, da);                                            // SRC_IN
    case 4: return mul8(d, sa);                                            // DST_IN
    case 5: return add(add(mul8(s, inv(da)), mul8(s, d)), mul8(d, inv(sa)));  // MULTIPLY
    case 6: return add(s, sub(d, mul8(s, d)));                             // SCREEN: no step saturates
    case 7: return std::min(src_over(s, d, sa), dst_over(s, d, da));       // DARKEN
    case 8: return std::max(src_over(s, d, sa), dst_over(s, d, da));       // LIGHTEN
    case 9: return add(s, d);                                              // ADDITIVE
    case 10: return mul8(d, inv(sa));                                      // SUBTRACT
    case 11: return add(mul8(s, sa), mul8(d, inv(sa)));                    // NORMAL_LVGL
    case 12: return add(mul8(add(s, d), sa), mul8(d, inv(sa)));            // ADDITIVE_LVGL
    case 13: return add(mul8(sub(d, s), sa), mul8(d, inv(sa)));            // SUBTRACT_LVGL
    case 14: return add(mul8(uint8_t(std::abs(int(d) - int(s))), sa), mul8(d, inv(sa)));  // DIFFERENCE_LVGL
    case 15: return add(mul8(mul8(s, d), sa), mul8(d, inv(sa)));           // MULTIPLY_LVGL
    default: return s;
  }
}

}  // namespace

Argb stencil_source(Argb i, Argb p, uint8_t ac[3]) {
  ac[0] = mul8(mul8(i.r, i.a), p.a);
  ac[1] = mul8(mul8(i.g, i.a), p.a);
  ac[2] = mul8(mul8(i.b, i.a), p.a);
  Argb s;
  s.a = mul8(i.a, p.a);
  s.r = mul8(p.r, ac[0]);
  s.g = mul8(p.g, ac[1]);
  s.b = mul8(p.b, ac[2]);
  return s;
}

Argb blend_stencil(unsigned mode, Argb s, Argb d, const uint8_t ac[3]) {
  Argb o;
  o.r = blend_ch(mode, s.r, d.r, ac[0], d.a);
  o.g = blend_ch(mode, s.g, d.g, ac[1], d.a);
  o.b = blend_ch(mode, s.b, d.b, ac[2], d.a);
  o.a = (mode >= 11 && mode <= 15) ? uint8_t(255) : blend_ch(mode, s.a, d.a, s.a, d.a);
  return o;
}

Argb blend(unsigned mode, Argb s, Argb d) {
  Argb o;
  o.r = blend_ch(mode, s.r, d.r, s.a, d.a);
  o.g = blend_ch(mode, s.g, d.g, s.a, d.a);
  o.b = blend_ch(mode, s.b, d.b, s.a, d.a);
  // Alpha rows of §5.6 are the colour rows with c = A, except the LVGL modes (A = 255).
  o.a = (mode >= 11 && mode <= 15) ? uint8_t(255) : blend_ch(mode, s.a, d.a, s.a, d.a);
  return o;
}

Argb coverage_blend(Argb d, Argb b, uint8_t cov) {
  if (cov == 255) return b;
  return Argb{lerp8(d.a, b.a, cov), lerp8(d.r, b.r, cov), lerp8(d.g, b.g, cov), lerp8(d.b, b.b, cov)};
}

// ---------------------------------------------------------------------------------------------
// §7 sampling
// ---------------------------------------------------------------------------------------------

namespace {

// floor((num) / den) for a 128-bit numerator and positive 64-bit denominator.
int64_t floor_div128(__int128 num, int64_t den) {
  __int128 q = num / den;
  if ((num % den != 0) && (num < 0)) --q;
  return static_cast<int64_t>(q);
}

}  // namespace

bool xform_map(const Xform& m, int x, int y, int64_t& u, int64_t& v) {
  const int64_t xh = 2 * int64_t(x) + 1, yh = 2 * int64_t(y) + 1;
  const int64_t U = int64_t(m.a) * xh + int64_t(m.b) * yh + 2 * int64_t(m.c);
  const int64_t V = int64_t(m.d) * xh + int64_t(m.e) * yh + 2 * int64_t(m.f);
  if (!m.persp) {
    u = U >> 1;
    v = V >> 1;
    return true;
  }
  const int64_t W = int64_t(m.g) * xh + int64_t(m.h) * yh + 2 * int64_t(m.i);
  if (W <= 0) return false;
  u = floor_div128(static_cast<__int128>(U) * (int64_t(1) << 30), W);
  v = floor_div128(static_cast<__int128>(V) * (int64_t(1) << 30), W);
  return true;
}

Argb bilinear(const Argb t[4], unsigned fx, unsigned fy) {
  const uint32_t w00 = (256 - fx) * (256 - fy), w10 = fx * (256 - fy), w01 = (256 - fx) * fy, w11 = fx * fy;
  auto ch = [&](uint8_t Argb::*c) {
    uint32_t s = t[0].*c * w00 + t[1].*c * w10 + t[2].*c * w01 + t[3].*c * w11;
    return uint8_t((s + 32768) >> 16);
  };
  return Argb{ch(&Argb::a), ch(&Argb::r), ch(&Argb::g), ch(&Argb::b)};
}

Argb gaussian(const Argb t[9], int32_t w0, int32_t w1, int32_t w2) {
  const int32_t w[9] = {w2, w1, w2, w1, w0, w1, w2, w1, w2};
  auto ch = [&](uint8_t Argb::*c) {
    int64_t s = 2048;
    for (int k = 0; k < 9; ++k) s += int64_t(t[k].*c) * w[k];
    const int64_t q = s >> 12;   // arithmetic: floor
    return uint8_t(q < 0 ? 0 : q > 255 ? 255 : q);
  };
  return Argb{ch(&Argb::a), ch(&Argb::r), ch(&Argb::g), ch(&Argb::b)};
}

bool wrap_coord(unsigned mode, int64_t x, int s0, int s1, int& out) {
  const int64_t n = s1 - s0, r = x - s0;
  auto mod = [](int64_t a, int64_t m) {
    const int64_t k = a % m;
    return k < 0 ? k + m : k;
  };
  switch (mode) {
    case 1:  // COLOR
      out = int(x);
      return x >= s0 && x < s1;
    case 3:  // REPEAT
      out = int(s0 + mod(r, n));
      return true;
    case 4: {  // REFLECT
      const int64_t k = mod(r, 2 * n);
      out = int(s0 + (k < n ? k : 2 * n - 1 - k));
      return true;
    }
    default:  // PAD, and the NONE clamp of the bilinear neighbours
      out = int(std::min<int64_t>(std::max<int64_t>(x, s0), s1 - 1));
      return true;
  }
}

// ---------------------------------------------------------------------------------------------
// §8 path coverage
// ---------------------------------------------------------------------------------------------

const uint8_t kSampleQ[16] = {4, 12, 8, 1, 15, 6, 10, 2, 13, 5, 9, 0, 14, 7, 3, 11};

void coverage_row(const std::vector<Edge>& edges, int py, int x0, int x1, bool aa, bool even_odd,
                  uint8_t* cov) {
  const int w = x1 - x0;
  if (w <= 0) return;
  const int nrows = aa ? 16 : 1;
  std::vector<int> delta(size_t(w) + 1);
  std::vector<uint8_t> count(size_t(w), 0);

  for (int j = 0; j < nrows; ++j) {
    // Sample row Y and the sample's X offset inside the pixel, in 1/32 px (§8.2).
    const int64_t Y = aa ? 32 * int64_t(py) + 2 * j + 1 : 32 * int64_t(py) + 16;
    const int64_t xoff = aa ? 2 * int64_t(kSampleQ[j]) + 1 : 16;
    std::fill(delta.begin(), delta.end(), 0);
    int base = 0;
    for (const Edge& e : edges) {
      if (e.y0 == e.y1) continue;
      const bool down = e.y1 > e.y0;
      const int64_t Xa = 2 * int64_t(down ? e.x0 : e.x1), Ya = 2 * int64_t(down ? e.y0 : e.y1);
      const int64_t Xb = 2 * int64_t(down ? e.x1 : e.x0), Yb = 2 * int64_t(down ? e.y1 : e.y0);
      if (!(Ya <= Y && Y < Yb)) continue;
      const int dir = down ? 1 : -1;
      // Crossing at or left of sample X  <=>  X >= ceil((Xa*dy + (Y-Ya)*dx) / dy)   (§8.3)
      const int64_t dy = Yb - Ya;
      const int64_t xt = ceil_div(Xa * dy + (Y - Ya) * (Xb - Xa), dy);
      // First pixel whose sample X = 32*px + xoff satisfies X >= xt.
      const int64_t p0 = ceil_div(xt - xoff, 32);
      if (p0 <= x0) base += dir;
      else if (p0 < x1) delta[size_t(p0 - x0)] += dir;
    }
    int wnd = base;
    for (int i = 0; i < w; ++i) {
      wnd += delta[size_t(i)];
      const int8_t w8 = static_cast<int8_t>(static_cast<uint8_t>(wnd & 0xFF));  // mod 256
      const bool inside = even_odd ? (w8 & 1) != 0 : w8 != 0;
      count[size_t(i)] += inside ? 1 : 0;
    }
  }
  for (int i = 0; i < w; ++i) {
    cov[i] = aa ? uint8_t((count[size_t(i)] * 255u + 8u) >> 4) : uint8_t(count[size_t(i)] ? 255 : 0);
  }
}

// ---------------------------------------------------------------------------------------------
// §5.7 blend families (v1.6)
// ---------------------------------------------------------------------------------------------

namespace {
uint8_t sat_add(uint32_t a, uint32_t b) { return uint8_t(a + b > 255 ? 255 : a + b); }
uint8_t sat_sub(uint32_t a, uint32_t b) { return uint8_t(a > b ? a - b : 0); }
uint8_t inv(uint32_t a) { return uint8_t(255 - a); }

// B.c from numerator n and result alpha ra (division by the result alpha)
uint8_t div_ra(uint32_t n, uint32_t ra) {
  if (ra == 0) return 0;
  if (n >= ra) return 255;
  return uint8_t((n * 255 + (ra >> 1)) / ra);
}

uint8_t svg_bf(unsigned mode, uint32_t cs, uint32_t cb) {
  switch (mode) {
    case 0: return uint8_t(cs);
    case 1: return mul8(cs, cb);
    case 2: return sat_add(cs, sat_sub(cb, mul8(cs, cb)));
    case 3: return uint8_t(cs > cb ? cs : cb);
    case 4: return uint8_t(cs < cb ? cs : cb);
    case 5: return uint8_t(cb > cs ? cb - cs : cs - cb);
    default: return sat_sub(sat_sub(sat_add(cs, cb), mul8(cs, cb)), mul8(cs, cb));
  }
}

uint8_t pd_cm(unsigned cm, bool src, uint32_t cs, uint32_t cd, uint32_t as, uint32_t ad) {
  switch (cm) {
    case 0: return src ? mul8(cs, as) : mul8(cd, ad);
    case 1: return uint8_t(cs);
    case 2: return uint8_t(cd);
    case 3: return sat_add(cs, cd);
    case 4: return sat_sub(cd, cs);
    case 5: return mul8(cs, cd);
    case 6: return uint8_t(cd > cs ? cd - cs : cs - cd);
    case 7: return sat_add(cs, sat_sub(cd, mul8(cs, cd)));
    case 8: return uint8_t(cs > cd ? cs : cd);
    case 9: return uint8_t(cs < cd ? cs : cd);
    case 10: return sat_sub(sat_sub(sat_add(cs, cd), mul8(cs, cd)), mul8(cs, cd));
    default: return uint8_t(src ? cs : cd);   // 15 BYPASS
  }
}

uint8_t pd_fc(unsigned f, uint32_t cs, uint32_t cd, uint32_t as, uint32_t ad, uint32_t ac, uint32_t cc) {
  switch (f) {
    case 0: return 0;
    case 1: return 255;
    case 2: return uint8_t(cs);
    case 3: return inv(cs);
    case 4: return uint8_t(as);
    case 5: return inv(as);
    case 6: return uint8_t(ad);
    case 7: return inv(ad);
    case 8: return uint8_t(cd);
    case 9: return inv(cd);
    case 10: return uint8_t(as < inv(ad) ? as : inv(ad));
    case 11: return uint8_t(ac);
    case 12: return inv(ac);
    case 13: return uint8_t(cc);
    case 14: return inv(cc);
    case 15: return sat_add(inv(ad), mul8(ad, cd));
    default: return inv(mul8(ad, cd));       // 16
  }
}

uint8_t pd_fa(unsigned f, uint32_t as, uint32_t ad, uint32_t ac) {
  switch (f) {
    case 0: return 0;
    case 1: return 255;
    case 2: return uint8_t(as);
    case 3: return inv(as);
    case 4: return uint8_t(ad);
    case 5: return inv(ad);
    case 6: return uint8_t(as < inv(ad) ? as : inv(ad));
    case 7: return uint8_t(ac);
    default: return inv(ac);                 // 8
  }
}

uint8_t pd_eq(unsigned eq, uint32_t fs, uint32_t xs, uint32_t fd, uint32_t xd) {
  switch (eq) {
    case 0: return sat_add(mul8(fs, xs), mul8(fd, xd));
    case 1: return sat_sub(mul8(fs, xs), mul8(fd, xd));
    case 2: return sat_sub(mul8(fd, xd), mul8(fs, xs));
    case 3: return uint8_t(xs < xd ? xs : xd);
    default: return uint8_t(xs > xd ? xs : xd);
  }
}
}  // namespace

bool blend_family_ok(unsigned family, unsigned mode, uint32_t func) {
  if (family == 1) return mode <= 9;
  if (family == 2) return mode <= 6;
  if (family == 3) {
    const unsigned fsa = func & 15, fsc = (func >> 4) & 31, fda = (func >> 9) & 15, fdc = (func >> 13) & 31;
    const unsigned eq = (func >> 18) & 7, scm = (func >> 21) & 15, dcm = (func >> 25) & 15;
    return fsa <= 8 && fda <= 8 && fsc <= 16 && fdc <= 16 && eq <= 4 && (scm <= 10 || scm == 15) &&
           (dcm <= 10 || dcm == 15);
  }
  return true;
}

Argb blend_family(unsigned family, unsigned mode, uint32_t func, Argb s, Argb d, Argb c) {
  const uint32_t sa = s.a, da = d.a;
  const uint8_t sc[3] = {s.r, s.g, s.b}, dc[3] = {d.r, d.g, d.b}, cc[3] = {c.r, c.g, c.b};
  uint8_t o[4];
  if (family == 3) {
    const unsigned fsa = func & 15, fsc = (func >> 4) & 31, fda = (func >> 9) & 15, fdc = (func >> 13) & 31;
    const unsigned eq = (func >> 18) & 7, scm = (func >> 21) & 15, dcm = (func >> 25) & 15;
    for (int k = 0; k < 3; ++k) {
      const uint32_t xs = pd_cm(scm, true, sc[k], dc[k], sa, da), xd = pd_cm(dcm, false, sc[k], dc[k], sa, da);
      o[k] = pd_eq(eq, pd_fc(fsc, sc[k], dc[k], sa, da, c.a, cc[k]), xs, pd_fc(fdc, sc[k], dc[k], sa, da, c.a, cc[k]), xd);
    }
    const uint32_t xs = pd_cm(scm, true, sa, da, sa, da), xd = pd_cm(dcm, false, sa, da, sa, da);
    o[3] = pd_eq(eq, pd_fa(fsa, sa, da, c.a), xs, pd_fa(fda, sa, da, c.a), xd);
  } else {
    uint32_t ra;
    if (family == 2) {
      ra = sat_add(sa, mul8(da, inv(sa)));
    } else {
      switch (mode) {
        case 0: ra = sa; break;
        case 2: ra = sat_add(mul8(sa, inv(da)), da); break;
        case 3: case 4: ra = mul8(sa, da); break;
        case 9: ra = sat_add(sa, da); break;
        default: ra = sat_add(sa, mul8(da, inv(sa))); break;
      }
    }
    for (int k = 0; k < 3; ++k) {
      const uint32_t sp = mul8(sc[k], sa), dp = mul8(dc[k], da);
      uint32_t n;
      if (family == 2) {
        n = sat_add(sat_add(mul8(sp, inv(da)), mul8(dp, inv(sa))), mul8(mul8(sa, da), svg_bf(mode, sc[k], dc[k])));
      } else {
        switch (mode) {
          case 0: n = sp; break;
          case 1: n = sat_add(sp, mul8(dp, inv(sa))); break;
          case 2: n = sat_add(mul8(sp, inv(da)), dp); break;
          case 3: n = mul8(sp, da); break;
          case 4: n = mul8(dp, sa); break;
          case 5: n = sat_add(sat_add(mul8(sp, dp), mul8(sp, inv(da))), mul8(dp, inv(sa))); break;
          case 6: n = sat_add(sp, sat_sub(dp, mul8(sp, dp))); break;
          case 7: case 8: {
            const uint32_t x = mul8(sp, da), y = mul8(dp, sa);
            const uint32_t mm = mode == 7 ? (x < y ? x : y) : (x > y ? x : y);
            n = sat_add(sat_add(mm, mul8(sp, inv(da))), mul8(dp, inv(sa)));
            break;
          }
          default: n = sat_add(sp, dp); break;
        }
      }
      o[k] = div_ra(n, ra);
    }
    o[3] = uint8_t(ra);
  }
  Argb r;
  r.r = o[0];
  r.g = o[1];
  r.b = o[2];
  r.a = o[3];
  return r;
}

// ---------------------------------------------------------------------------------------------
// §10 gradient
// ---------------------------------------------------------------------------------------------

int grad_index(int32_t p, int32_t q, int64_t r, int x, int y, unsigned spread) {
  const int64_t T = int64_t(p) * (2 * int64_t(x) + 1) + int64_t(q) * (2 * int64_t(y) + 1) + r;
  return spread_index(T >> 17, spread);
}

uint64_t isqrt64(uint64_t v) {
  // digit by digit, two argument bits per result bit (the RTL's g2d_isqrt does the same per stage)
  uint64_t root = 0, rem = 0;
  for (int k = 31; k >= 0; --k) {
    rem = (rem << 2) | ((v >> (2 * k)) & 3u);
    const uint64_t t = (root << 2) | 1u;
    root <<= 1;
    if (rem >= t) {
      rem -= t;
      root |= 1u;
    }
  }
  return root;
}

int radial_index(const int32_t p[3], const int32_t q[3], const int64_t r[3], int x, int y, unsigned spread) {
  int64_t f[3];
  for (int k = 0; k < 3; ++k) f[k] = int64_t(p[k]) * (2 * int64_t(x) + 1) + int64_t(q[k]) * (2 * int64_t(y) + 1) + r[k];
  auto sat32 = [](int64_t v) { return v < INT32_MIN ? int64_t(INT32_MIN) : v > INT32_MAX ? int64_t(INT32_MAX) : v; };
  const int64_t u = sat32(f[1] >> 9), v = sat32(f[2] >> 9);
  const uint64_t s = isqrt64(uint64_t(u * u) + uint64_t(v * v));   // <= 2^63, exact in 64 bits
  return spread_index(((f[0] >> 9) + int64_t(s)) >> 8, spread);
}

int spread_index(int64_t i, unsigned spread) {
  switch (spread) {
    case 1:
      return int(i & 255);
    case 2: {
      const int64_t k = i & 511;
      return int(k < 256 ? k : 511 - k);
    }
    case 3:
      return (i < 0 || i > 255) ? -1 : int(i);
    default:
      return int(i < 0 ? 0 : (i > 255 ? 255 : i));
  }
}

}  // namespace g2d
